/// A question's parameters: the snapshot and project, then the fields of what it asks.
#[derive(Serialize)]
struct Scoped<'a> {
    project: &'a str,
    snapshot: u64,
    #[serde(flatten)]
    ask: Ask<'a>,
}

impl Request for Scoped<'_> {
    fn method(&self) -> &'static str {
        self.ask.method()
    }
}

