1733	    /// Checks `params`, sent as `name`, against what tsrs reads of it, and the objects nested in it against theirs;
1734	    /// returns each mismatch.
1735	    fn mismatches(name: &str, params: &Value) -> Vec<String> {
1736	        let Some((_, required, optional)) = TSRS_READS.iter().find(|(known, _, _)| *known == name) else {
1737	            return vec![format!("{name}: not in the table of what tsrs reads")];
1738	        };
1739	        let Some(object) = params.as_object() else {
1740	            return if required.is_empty() && params.is_null() { vec![] } else { vec![format!("{name}: {params}")] };
1741	        };
1742	        let mut wrong: Vec<String> = Vec::new();
1743	        for key in object.keys() {
1744	            if !required.contains(&key.as_str()) && !optional.contains(&key.as_str()) {
1745	                wrong.push(format!("{name}: sends `{key}`, which tsrs does not read"));
1746	            }
1747	        }
1748	        for key in *required {
1749	            if !object.contains_key(*key) {
1750	                wrong.push(format!("{name}: does not send `{key}`"));
1751	            }
1752	        }
1753	        let each = |value: &'_ Value, key: &str| value.get(key).and_then(Value::as_array).cloned().unwrap_or_default();
1754	        // `createSnapshot` takes the changes as its parameters, `updateSnapshot` under `changes`; either way the
1755	        // objects nested in the changes are checked once, at the level that holds them.
1756	        if let Some(changes) = object.get("changes") {
1757	            wrong.extend(mismatches("CreateSnapshotParams", changes));
1758	        }
1759	        if let Some(notified) = object.get("fileNotifications") {
1760	            wrong.extend(mismatches("FileNotifications", notified));
1761	        }
1762	        for program in each(params, "createPrograms") {
1763	            wrong.extend(mismatches("CreateSnapshotProgramParams", &program));
1764	        }
1765	        for program in each(params, "reconfigurePrograms") {
1766	            wrong.extend(mismatches("ReconfigureSnapshotProgramParams", &program));
1767	        }
1768	        for request in each(params, "requests") {
1769	            wrong.extend(mismatches("BatchRequest", &request));
1770	            wrong.extend(mismatches(request["method"].as_str().unwrap_or_default(), &request["params"]));
1771	        }
1772	        wrong
1773	    }
